// Construye el prompt para Gemini segun el tipo de tarea.
const task = $input.all()[0].json;
const t = task.tarea;
const p = (t && t.payload) || {};
let instruccion = '';
let texto = '';
if (t.tipo === 'moderar_post') {
  instruccion = 'Eres el moderador de Adoptify (plataforma de adopcion de mascotas). Analiza esta PUBLICACION del foro y responde SOLO JSON: {"decision": "aprobar"|"marcar"|"ocultar", "confianza": 0.0-1.0, "motivo": "corto en espanol", "sugerencias": "como reescribirlo"}. Oculta SOLO spam/insultos graves/ilegal (confianza alta); marca lo dudoso; aprueba el resto.\n\n';
  texto = (p.titulo || '') + '\n' + (p.contenido || '');
} else if (t.tipo === 'moderar_comentario') {
  instruccion = 'Eres el moderador de comentarios de Adoptify. Analiza este COMENTARIO del foro y responde SOLO JSON: {"decision": "aprobar"|"marcar"|"ocultar", "confianza": 0.0-1.0, "motivo": "...", "sugerencias": "..."}. Oculta SOLO spam/insultos graves; marca groserias leves; aprueba el resto.\n\n';
  texto = p.contenido || '';
} else if (t.tipo === 'moderar_producto') {
  instruccion = 'Eres el moderador del marketplace de Adoptify. Analiza este PRODUCTO y responde SOLO JSON: {"decision": "aprobar"|"marcar"|"ocultar", "confianza": 0.0-1.0, "motivo": "...", "sugerencias": "..."}. Oculta solo contenido inapropiado, prohibido o spam.\n\n';
  texto = (p.nombre || '') + '\n' + (p.descripcion_larga || p.descripcion || '');
} else if (t.tipo === 'moderar_mascota') {
  instruccion = 'Eres el moderador de Adoptify. Analiza la ficha de esta MASCOTA y responde SOLO JSON: {"decision": "aprobar"|"marcar"|"ocultar", "confianza": 0.0-1.0, "motivo": "...", "sugerencias": "..."}.\n\n';
  texto = (p.nombre || '') + '\n' + (p.descripcion || '') + '\n' + (p.personalidad || '');
} else if (t.tipo === 'clasificar_pqrs') {
  instruccion = 'Clasifica esta PQRS de una tienda de Adoptify. Responde SOLO JSON: {"categoria": "pago"|"envio"|"producto"|"plataforma"|"otro", "prioridad": "alta"|"media"|"baja", "resumen": "una frase corta en espanol"}.\n\n';
  texto = (p.asunto || '') + '\n' + (p.descripcion || '');
} else if (t.tipo === 'clasificar_reporte') {
  instruccion = 'Clasifica este REPORTE de contenido de Adoptify. Responde SOLO JSON: {"categoria": "spam"|"abuso"|"contenido_inapropiado"|"estafa"|"otro", "prioridad": "alta"|"media"|"baja", "resumen": "una frase corta en espanol"}.\n\n';
  texto = (p.tipo_objeto || '') + ': ' + (p.motivo || '');
} else {
  instruccion = 'Analiza el contenido y responde SOLO JSON.\n\n';
  texto = JSON.stringify(p);
}
return [{ json: { tipo: t.tipo, tarea_id: t.id, prompt: instruccion + texto } }];

// Extrae y valida el JSON que devuelve Gemini y lo entrega a la tarea.
const r = $input.all()[0].json;
const tareaId = $('Construir texto').first().json.tarea_id;
let texto = '';
try {
  texto = r.candidates[0].content.parts[0].text;
} catch (e) {
  texto = '';
}
if (!texto) {
  return [{ json: { tarea_id: tareaId, resultado: null, error: 'Respuesta vacia de Gemini' } }];
}
texto = texto.trim();
if (texto.startsWith('```json')) texto = texto.slice(7);
else if (texto.startsWith('```')) texto = texto.slice(3);
if (texto.endsWith('```')) texto = texto.slice(0, -3);
texto = texto.trim();
try {
  const resultado = JSON.parse(texto);
  return [{ json: { tarea_id: tareaId, resultado, error: null } }];
} catch (e) {
  return [{ json: { tarea_id: tareaId, resultado: null, error: 'JSON invalido devuelto por Gemini' } }];
}
